* 1. Operating Point analysis
op
let idd = -i(VDD)
let vocm = (v(vop) + v(vom)) / 2
print idd vocm v(Vbiasn) v(Vbiasp) v(VCMFB)

* 2. DC Sweep as in Fig. 26.30 / 26.34
dc Vp 480m 520m 0.2m
let diff_out = v(vop) - v(vom)
let gain_deriv = deriv(diff_out)
meas dc max_gain max gain_deriv
meas dc v_out_max max v(vop)
meas dc v_out_min min v(vop)
let v_swing = v_out_max - v_out_min
print max_gain v_out_max v_out_min v_swing

* 3. AC Frequency Response
ac dec 20 10k 10G
let a_diff_db = vdb(vop, vom)
meas ac dc_gain find a_diff_db at=10k
meas ac ugbw when a_diff_db=0 fall=1
print dc_gain ugbw

quit
.endc
.end

